<script>
   /*************************************************************/
   /* AppContainer for target test                              */
   /* -------------------------                                 */
   /* app container for applying DD-SIMCA model to target class */
   /*************************************************************/

   import { untrack } from 'svelte';
   import { Container, Button } from 'svelte-controls-basic';
   import { pcamodel_get, pcares_get } from '@mdatools-apps/wasm/pca.js';
   import { replacer } from '@mdatools-apps/shared/utils';
   import { downloadResults, downloadModel, predict } from '@mdatools-apps/shared/methods/simca.js';

   import DataLoader from '@mdatools-apps/shared/components/pca/DataLoader.svelte';
   import Outliers from '@mdatools-apps/shared/widgets/Outliers.svelte';
   import Contributions from '@mdatools-apps/shared/components/Contributions.svelte';

   import ModelLoader from '../shared/ModelLoader.svelte';
   import ModelTable from '../shared/ModelTable.svelte';
   import SIMCASettings from '../shared/SIMCASettings.svelte';

   import ResultTable from './ResultTable.svelte';
   import AppPlots from './AppPlots.svelte';

   // WASM promise and session object from parent app
   let {WASM, backupSession, session = $bindable()} = $props();

   // get part of the session for this tab
   const s = $derived(session['test']);

   // properties for showing contributions
   let selected = $state(-1);
   let contributionIsShown = $state(false);


   // callback function to set object with a give position in plot series
   // as outlier
   function markOutlier(pos) {

      // check that position is valid
      if (pos < 0 || pos > s.testres.pca.nrows - 1) return;

      // find sample ID corresponding to the position
      // this is needed if some of the objects already
      // removed from results as outliers
      const id = s.testres.pca.objindices[pos];

      // add the object to outliers array and reset the model and all related outcomes
      if (id >= 0 && !s.outliers.includes(id)) {
         s.outliers.push(id);
         s.testres.simca = null;
         s.testres.pca = null;
      }
   }

   // show modal dialog with contributions for selected object
   function showContributions(pos) {
      if (pos < 0) return;
      selected = pos;
      contributionIsShown = true;
   }

   // hide modal dialog with contributions
   function hideContributions() {
      contributionIsShown = false;
      selected = -1;
   }

   // callback to reset outliers
   function resetOutliers() {
      s.outliers = [];
      s.testres.simca = null;
      s.testres.pca = null;
   }

   // callback to undo outliers
   function undoOutliers() {
      s.outliers.pop();
      s.testres.simca = null;
      s.testres.pca = null;
   }

   // pre-rendering effect to avoid bad structure of the session object
   $effect.pre(() => {

      // if test set is set null - reset results and all related parameters
      if (s.testset === null) {
         s.outliers = [];
         s.testres.simca = null;
         s.testres.pca = null;
         s.ind = null;
      }

      // if model object is set to null - reset dependent objects
      if (s.model === null) {
         s.testres.simca = null;
         s.testres.pca = null;
         s.testset = null;
         s.outliers = [];
         s.simca = null;
      }

   });

   // if model object is set to null - reset dependent objects
   $effect(() => {
      if (s.model === null) {
         s.outliers = [];
         s.testres.simca = null;
         s.testres.pca = null;
         s.testset = null;
         s.simca = null;
      }
   });

   // if test set is set null - reset results and all related parameters
   $effect(() => {
      if (s.testset === null) {
         s.outliers = [];
         s.testres.simca = null;
         s.testres.pca = null;
         s.ind = null;
      }
   });

   $effect(() => {
      if (!s.testres.pca || !s.simca || s.testres.pca.classes.length < 1)  return;

      const classes = s.testres.pca.classes;
      const members = [];
      const strangers = [];

      for (let i = 0; i < classes.length; i++) {
         if (classes[i] === s.simca.className) {
            members.push(i);
         } else {
            strangers.push(i);
         }
      }
      s.ind = {members, strangers};
   });

   // effects to track changes in eCrit and oCrit for recalculations of simca results
   $effect(() => {
      if (s.testres.pca && s.simca && s.ind) {
         s.testres.simca = predict(s.testres.pca, untrack(() => s.simca.limType), s.simca.eCrit, s.simca.oCrit, s.ind)
      }
   });


   // reactive effect for backing up the session. the string is built by 'backupSession' when the
   // write is due, not here, and the first run is skipped: it only ever coincides with a session
   // the app was given as a whole, which is already on disk, is written by 'MainApp' itself, or is
   // a fresh one that need not be stored. the values after the function are the dependencies (see
   // 'backupSession')
   let mounted = false;
   $effect(() => {
      const deps = s.simca ? [s.model, s.testset, s.simca.ncomp, s.testres.simca] :
         [s.model, s.testset, s.simca, s.testres.simca];
      if (mounted) backupSession(() => JSON.stringify(session, replacer), ...deps);
      mounted = true;
   });
</script>


{#if contributionIsShown && s.simca && s.model && s.testres.pca}
   <Contributions
      model_getter={pcamodel_get}
      res_getter={pcares_get}
      model={s.model}
      res={{'test': s.testres.pca}}
      closeModal={hideContributions}
      ncomp={s.simca.ncomp}
      {selected}
   />
{/if}

<div class="app-container">

   <!-- left column with main app controls -->
   <div class="app-controls">
      <div class="model-loader">
         <ModelLoader bind:model={s.model} bind:simca={s.simca} />
      </div>

      {#if s.model}
      <div class="data-loader">
         <DataLoader
            bind:dataset={s.testset}
            bind:resobj={s.testres.pca}
            outliers={s.outliers}
            {WASM}
            model={s.model}
            className="Class"
            classMandatory={true}
         />
      </div>
      {/if}

      {#if s.outliers && s.outliers.length > 0 }
      <div class="outliers-pane">
         <Outliers outliers={s.outliers} dataset={s.testset} {resetOutliers} {undoOutliers} />
      </div>
      {/if}

      <div class="simca-settings">

         {#if s.model && s.testres.pca }
         <SIMCASettings
            model={s.model}
            bind:simca={s.simca}
            isAlt={s.ind && s.ind.members.length < 1}
         />
         {/if}

         {#if s.simca && s.model && s.testres.simca }
         <Container label='Download'>
            <div class="buttons">
            <Button onclick={() => downloadResults(s.model, s.simca, s.testres, s.testset, "test")} text="Res (test)"/>
            <Button onclick={() => downloadModel(s.model, s.simca)} text="Model" />
            </div>
         </Container>
         {/if}
      </div>

      {#if s.model && s.simca && s.testres.simca}
      <div class="model-stats">
         <ModelTable model={s.model} simca={s.simca} />
      </div>
      <div class="result-stats">
         <ResultTable res={s.testres.simca} ncomp={s.simca.ncomp}/>
      </div>
      {/if}
   </div>


   <!-- right column with help text or with plots and plot controls -->
   <div class="app-content">
      {#if !s.testres.simca}
         <div class="help-text">
         <p>
            In this tab you can apply previously trained DD-SIMCA model to a test set. The test set can include target class members,
            objects belonging to alternative classes or both. You can use them for testing performance
            of the model, or tune its parameters, if necessary.
         </p>
         {#if !s.model}
            <p><strong>Step 1</strong></p>
            <p>
               Load previously trained DD-SIMCA model from file.
            </p>
         {:else}
            {#if !s.testset}
            <p><strong>Step 2</strong></p>
            <p>
               Load test set from CSV file. The requirements to the file are the same as for the training set (column with
               class labels is mandatory), but test set may contain class labels both for target class (members) as well as for
               alternative classes (strangers).
            </p>
            {/if}
         {/if}

         </div>
      {:else}
         {#if s.model && s.simca && s.testres.pca}
         {#key s.testres.pca }
         <AppPlots {markOutlier} {showContributions} {...s} />
         {/key}
         {/if}
      {/if}
   </div>
</div>

